// 原信件由原TransferLots唯一移动；本叶在其前后核对一份实物与直接参与者，然后登记一次收据。
#include "task_message_handoff.hpp"
#include <limits>
namespace hanmo::resident {
namespace {
Outcome<Integer> observed_tick(const CommonStore& common,const DynamicStepInput* phase){if(!phase)return {true,common.tick(),{}};if(phase->from_tick!=common.tick()||phase->from_tick<0||phase->from_tick==std::numeric_limits<Integer>::max()||phase->to_tick!=phase->from_tick+1)return {false,{},common_failure("TaskMessageHandoffPhaseMismatch").error};return {true,phase->to_tick,{}};}
Owner actor_owner(const StableId& id){return {Owner::Kind::actor,id,{}};}
bool contains(const std::vector<StableId>& values,const StableId& id){return std::find(values.begin(),values.end(),id)!=values.end();}
}
Outcome<TaskMessageHandoffPreparation> prepare_task_message_handoff(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const TaskMessageHandoffState& state,const ActionCoreView& action,Integer tick,const DynamicStepInput* phase){
    const auto fail=[](const StableId& code)->Outcome<TaskMessageHandoffPreparation>{return {false,{},common_failure(code).error};};
    if((state.version!=1&&state.version!=2&&state.version!=3&&state.version!=4))return fail("UnsupportedTaskMessageHandoffVersion");auto observed=observed_tick(common,phase);if(!observed.ok)return {false,{},observed.error};if(tick!=observed.value)return fail("TaskMessageHandoffTickMismatch");
    const auto* params=tasks.actions.find(action.id);const auto* task=params?tasks.tasks.find(params->task_id):nullptr;const auto* definition=task?catalog.offers.find(task->offer_id):nullptr;const auto* live=common.action(action.id);
    if(!task||task->contract_id||!definition||definition->template_id!="message"||!live||live->kind!="deliver_message"||action.kind!=live->kind||action.actor_id!=live->actor_id||task->assignee!=action.actor_id||params->offer_id!=definition->id||params->context.provider_actor_id!=definition->goal.receiver_actor||task->status!="active"||task->objective_completed_tick||!task->settlement_id.empty())return fail("InvalidTaskMessageHandoffAction");
    for(const auto& row:state.receipts.rows())if(row.second.task_id==task->id||row.second.source_action_id==action.id)return fail("DuplicateTaskMessageHandoff");
    const auto* carrier=common.actor(task->assignee);const auto* recipient=common.actor(definition->goal.receiver_actor);const auto* role=shared.roles.find(params->context.role_id);const auto* assigned=common.state().roles.find(params->context.role_id);
    if(!carrier||!recipient||carrier->id==recipient->id||!carrier->alive||!recipient->alive||!carrier->available||!recipient->available||carrier->action_id!=action.id||recipient->action_id!=action.id||!contains(live->participants,carrier->id)||!contains(live->participants,recipient->id)||!role||!assigned||!assigned->enabled||assigned->actor_id!=recipient->id||role->place_id!=params->context.place_id||!contains(role->services,"deliver_message"))return fail("InvalidTaskMessageHandoffParticipants");
    auto from=common.resolved_location(carrier->id),to=common.resolved_location(recipient->id);const auto* a=from.ok?std::get_if<SettlementLocation>(&from.value):nullptr;const auto* b=to.ok?std::get_if<SettlementLocation>(&to.value):nullptr;
    if(!a||!b||a->place_id!=params->context.place_id||b->place_id!=a->place_id||a->settlement_id!=b->settlement_id||!shared.places.find(a->place_id))return fail("TaskMessageHandoffNotPresent");
    const auto* source=common.inventory(carrier->inventory_id);const auto* destination=common.inventory(recipient->inventory_id);const Owner task_owner{Owner::Kind::task,task->id,{}};
    if(!source||!destination||source->id==destination->id||!owner_equal(source->owner,actor_owner(carrier->id))||!owner_equal(destination->owner,actor_owner(recipient->id)))return fail("TaskMessageHandoffCustodyMismatch");
    const LotView* letter=nullptr;for(const auto& lot:source->lots)if(lot.item_id==definition->goal.message_id&&owner_equal(lot.owner,task_owner)){if(letter||lot.quantity!=1||lot.reserved_by!=ReservationRef{action.id})return fail("TaskMessageHandoffLetterMismatch");letter=&lot;}if(!letter)return fail("TaskMessageHandoffLetterMissing");
    auto quantity=common.count(destination->id,definition->goal.message_id,{actor_owner(recipient->id)});if(!quantity.ok)return {false,{},quantity.error};if(quantity.value==std::numeric_limits<Integer>::max())return fail("TaskMessageHandoffQuantityOverflow");
    TaskMessageHandoffPreparation out;out.recipient_quantity_before=quantity.value;for(const auto& lot:destination->lots)out.recipient_lots_before.push_back(lot.id);auto& receipt=out.receipt;receipt.task_id=task->id;receipt.offer_id=definition->id;receipt.source_action_id=action.id;receipt.original_issuer=definition->issuer;receipt.carrier_actor_id=carrier->id;receipt.recipient_actor_id=recipient->id;receipt.item_id=letter->item_id;receipt.source_lot_id=letter->id;receipt.from_inventory_id=source->id;receipt.to_inventory_id=destination->id;receipt.place_id=a->place_id;receipt.role_id=role->id;receipt.tick=tick;return {true,std::move(out),{}};
}
Status record_task_message_handoff_after_resources(CommonStore& common,TaskMessageHandoffState& state,const TaskMessageHandoffPreparation& prepared){
    const auto& source=prepared.receipt;if((state.version!=1&&state.version!=2&&state.version!=3&&state.version!=4)||!source.fact_id.empty()||!source.recipient_lot_id.empty())return common_failure("InvalidTaskMessageHandoffPreparation");
    for(const auto& row:state.receipts.rows())if(row.second.task_id==source.task_id||row.second.source_action_id==source.source_action_id)return common_failure("DuplicateTaskMessageHandoff",source.task_id);
    const auto* from=common.inventory(source.from_inventory_id);const auto* to=common.inventory(source.to_inventory_id);if(!from||!to)return common_failure("TaskMessageHandoffCustodyMismatch");
    for(const auto& lot:from->lots)if(lot.id==source.source_lot_id||(lot.item_id==source.item_id&&owner_equal(lot.owner,Owner{Owner::Kind::task,source.task_id,{}})))return common_failure("TaskMessageHandoffNotTransferred");
    auto quantity=common.count(to->id,source.item_id,{actor_owner(source.recipient_actor_id)});if(!quantity.ok)return {false,{},quantity.error};if(prepared.recipient_quantity_before<0||prepared.recipient_quantity_before==std::numeric_limits<Integer>::max()||quantity.value!=prepared.recipient_quantity_before+1)return common_failure("TaskMessageHandoffNotTransferred");
    StableId delivered;for(const auto& lot:to->lots)if(!contains(prepared.recipient_lots_before,lot.id)){if(!delivered.empty()||lot.item_id!=source.item_id||lot.quantity!=1||!lot.reserved_by.empty()||!owner_equal(lot.owner,actor_owner(source.recipient_actor_id)))return common_failure("TaskMessageHandoffTransferredLotMismatch");delivered=lot.id;}if(delivered.empty())return common_failure("TaskMessageHandoffTransferredLotMissing");
    auto id=common.next_id("task_message_handoff");if(!id.ok)return {false,{},id.error};auto receipt=source;receipt.fact_id=id.value;receipt.recipient_lot_id=std::move(delivered);auto fact=common.append_fact({receipt.fact_id,task_message_handoff_kind,"tasks"});if(!fact.ok)return fact;if(!state.receipts.insert(id.value,std::move(receipt)))return common_failure("DuplicateTaskMessageHandoff",id.value);state.observed_by[source.carrier_actor_id].push_back(id.value);state.observed_by[source.recipient_actor_id].push_back(id.value);return common_success();
}
}
